41	const PROCESSING_FEE = 5;
42	
43	const FIRST_INSURANCE_PERCENT = 10;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	// Percentages MUST go through this helper. Applying them as exact integer
55	// fractions keeps the arithmetic drift-free; the tempting `amount * 1.1`
56	// yields 110.00000000000001 for 100, and since the spec rounds premiums UP
57	// at the very end that drift becomes a whole extra G.
58	const addPercent = (amount: number, percent: number): number =>
59	  (amount * (100 + percent)) / 100;
60	
61	const BLOCK_SIZE = 3;
62	const BLOCK_BASE_PREMIUM = 60;
63	
64	const countByType = (items: Item[]): Map<string, number> => {
65	  const counts = new Map<string, number>();
66	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
67	
68	  return counts;
69	};
70	
71	const basePremiumForType = (type: string, count: number): number =>
72	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
73	
74	const quote = ({ items }: QuoteStep): StepResult => {
75	  let policyBase = 0;
76	  for (const [type, count] of countByType(items)) {
77	    policyBase += basePremiumForType(type, count);
78	  }
79	  const withFirstInsurance = addPercent(policyBase, FIRST_INSURANCE_PERCENT);
80	
81	  return { premium: Math.ceil(withFirstInsurance + PROCESSING_FEE) };
82	};
83	
84	export const runScenario = (scenario: Scenario): ScenarioResult => ({
85	  // Only quote steps are exercised so far; claim dispatch arrives with its first test.
86	  results: scenario.steps.map((step) => quote(step as QuoteStep)),
87	});
